# COMMAND CENTER existing-client update. Exact committed code; no ZIP.
[CmdletBinding()]
param()
$ErrorActionPreference='Stop'
$stage=Join-Path ([IO.Path]::GetTempPath()) ('cc-existing-client-'+[guid]::NewGuid().ToString('N'))
$resultCode=1
try {
 $null=New-Item -ItemType Directory -Path $stage
 $entries=@{
  'clean-room/src/worker/pc-worker-cli.mjs'=''
  'clean-room/src/worker/pc-worker-supervisor.mjs'=''
  'clean-room/src/worker/pc-worker-transport.mjs'=''
  'clean-room/src/brain/pc-local-ollama.mjs'=''
  'clean-room/src/brain/pc-owner-inference-worker.mjs'=''
  'clean-room/src/brain/pc-brain-readiness.mjs'=''
  'clean-room/src/brain/pc-activation-contract.mjs'=''
  'clean-room/src/worker/pc-artifact-job-runner.mjs'=''
  'clean-room/src/worker/pc-activation-exchange-runner.mjs'=''
  'clean-room/src/worker/pc-activation-exchange-transport.mjs'=''
  'clean-room/src/worker/pc-tool-job-transport.mjs'=''
  'clean-room/src/worker/pc-tool-execution-lane.mjs'=''
  'clean-room/src/worker/pc-tool-journal.mjs'=''
  'clean-room/src/worker/pc-project-file-tool.mjs'=''
  'clean-room/src/brain/tool-runtime.mjs'=''
  'clean-room/src/brain/tool-access.mjs'=''
 }
 foreach($relative in $entries.Keys){
  if($relative -notmatch '^clean-room/src/(worker|brain)/[a-z0-9-]+\.mjs$'){throw 'Embedded source path invalid.'}
  $path=Join-Path (Join-Path $stage 'payload') ($relative.Replace('/',[IO.Path]::DirectorySeparatorChar))
  $null=New-Item -ItemType Directory -Path (Split-Path $path) -Force
  [IO.File]::WriteAllBytes($path,[Convert]::FromBase64String($entries[$relative]))
 }
 [IO.File]::WriteAllBytes((Join-Path $stage 'UPDATE_MANIFEST.json'),[Convert]::FromBase64String(''))
 $entry=Join-Path $stage 'UPDATE_EXISTING_WORKER.ps1'
 [IO.File]::WriteAllBytes($entry,[Convert]::FromBase64String(''))
 if((Get-FileHash -LiteralPath $entry -Algorithm SHA256).Hash.ToLowerInvariant() -ne '39c7812d6d5a0d62f908ad79174e5261a62577f234048255d6185508f8e3b077'){throw 'Embedded updater hash mismatch.'}
 # Local bytes just decoded from the exact outer script verified by its caller.
 & $entry
 $resultCode=$LASTEXITCODE
 if($null -eq $resultCode){$resultCode=0}
}finally {
 if(Test-Path -LiteralPath $stage){Remove-Item -LiteralPath $stage -Recurse -Force}
}
if($resultCode -ne 0){throw 'Existing client update did not complete. See the UPDATE STOPPED reason above.'}
